/*
 Problem: 678. Valid Parenthesis String
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.1 MB (76.19%)
 Tags: Dynamic Programming, Greedy, Stack, String
*/
class Solution {
public:
    bool checkValidString(string s) {
        int p1 = 0;
        int p2 = 0;

        for (auto& c : s) {
            if (c == '(')
            {
                ++p1;
                ++p2;
            }
            else if (c == '*')
                {
                    ++p1;
                    --p2;
                }
            else {
                --p1;
                --p2;
            }

            if (p1 < 0)
                return false;

            if (p2 < 0)
                p2 = 0;
        }

        return p2 == 0;
    }
};
